$pageTitle='Audio archive'; require_once 'includes/auth.php'; require_auth(); $u=current_user(); $uploadDir=__DIR__.'/uploads'; if(!is_dir($uploadDir))mkdir($uploadDir,0755,true);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(empty($_FILES['audio']['tmp_name'])||$_FILES['audio']['error']!==UPLOAD_ERR_OK){flash('error','Please record or choose a valid audio file.');}else{$ext=strtolower(pathinfo($_FILES['audio']['name'],PATHINFO_EXTENSION));if(!in_array($ext,['wav','webm','ogg','mp3'],true)||$_FILES['audio']['size']>25*1024*1024){flash('error','Audio must be WAV, WebM, OGG, or MP3 under 25 MB.');}else{$filename=bin2hex(random_bytes(16)).'.'.$ext;move_uploaded_file($_FILES['audio']['tmp_name'],$uploadDir.'/'.$filename);$s=$pdo->prepare('INSERT INTO audio_logs(company_id,project_id,user_id,filename,label,duration_sec) VALUES(?,?,?,?,?,?)');$s->execute([$u['company_id'],(int)($_POST['project_id']?:0)?:null,$u['id'],$filename,trim($_POST['label']),(int)($_POST['duration']??0)]);flash('success','Audio saved to the archive.');}}header('Location: audio.php');exit;}
$s=$pdo->prepare('SELECT id,name FROM projects WHERE company_id=? ORDER BY name');$s->execute([$u['company_id']]);$projects=$s->fetchAll();$s=$pdo->prepare('SELECT a.*,p.name project_name FROM audio_logs a LEFT JOIN projects p ON p.id=a.project_id WHERE a.company_id=? ORDER BY a.created_at DESC');$s->execute([$u['company_id']]);$logs=$s->fetchAll();$suggestions=[];foreach($logs as $log){$q=$pdo->prepare('SELECT * FROM ai_task_suggestions WHERE audio_id=? ORDER BY created_at DESC');$q->execute([$log['id']]);$suggestions[$log['id']]=$q->fetchAll();}require 'includes/header.php';
?><style>.priority{display:inline-block;padding:4px 8px;border-radius:4px;font-size:10px;font-weight:800;text-transform:uppercase}.priority.urgent{background:#fee2e2;color:#b91c1c}.priority.important{background:#fef3c7;color:#92400e}.priority.normal{background:#dcfce7;color:#166534}.ai-box{margin-top:12px;padding:10px;background:#f8fafc;border:1px solid var(--line);font-size:12px}.ai-box form{display:inline-flex;gap:6px;align-items:center;margin:5px 5px 0 0}</style><div class="grid grid-2"><section class="card audio-recorder" id="recorder"><div class="rec-dot" id="recordButton"></div><div class="timer" id="timer">00:00</div><div class="visualizer"><?php for($i=0;$i<18;$i++): ?><i></i><?php endfor; ?></div><p class="muted" id="recordHint">Press the button to start a meeting recording.</p><form method="post" enctype="multipart/form-data" id="audioForm"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="duration" id="duration"><div class="field" style="text-align:left;margin-top:20px"><label>Recording label</label><input name="label" placeholder="e.g. Weekly product sync"></div><div class="field" style="text-align:left;margin-top:12px"><label>Assign to project</label><select name="project_id"><option value="">No project</option><?php foreach($projects as $p): ?><option value="<?=$p['id']?>" <?=((int)($_GET['project']??0)==$p['id'])?'selected':''?>><?=e($p['name'])?></option><?php endforeach; ?></select></div><input type="file" name="audio" id="audioFile" accept="audio/*" hidden><div class="form-actions"><button type="button" class="button button-light" onclick="document.getElementById('audioFile').click()">Choose audio file</button><button class="button button-red" id="saveButton" disabled>Save recording</button></div></form></section><section><div class="section-head" style="margin-top:0"><h2>Recent recordings</h2></div><div class="card" style="padding:8px 18px"><div class="empty" style="padding:20px 0"><?=count($logs)?> recording(s) in your archive.</div><?php foreach($logs as $log): ?><div style="padding:15px 0;border-top:1px solid var(--line)"><div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:7px"><strong><?=e($log['label']?:'Untitled recording')?></strong><span class="muted"><?=e(date('M j, Y · H:i',strtotime($log['created_at'])))?></span></div><div class="muted" style="margin-bottom:8px"><?=e($log['project_name']?:'Unassigned project')?></div><audio controls preload="none" src="uploads/<?=e($log['filename'])?>"></audio><div class="ai-box"><form method="post" action="audio_ai.php"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="audio_id" value="<?=$log['id']?>"><input type="hidden" name="action" value="transcribe"><select name="language"><option value="">Auto language</option><option value="en">English</option><option value="tr">Turkish</option></select><button class="button button-light">Transcribe</button></form><?php if(trim((string)$log['transcript'])!==''): ?><form method="post" action="audio_ai.php"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="audio_id" value="<?=$log['id']?>"><input type="hidden" name="action" value="suggest"><button class="button button-light">Create AI task suggestions</button></form><details style="margin-top:10px"><summary><strong>Transcript</strong></summary><p style="white-space:pre-wrap;color:var(--muted);line-height:1.55"><?=e($log['transcript'])?></p></details><?php endif; ?><?php foreach($suggestions[$log['id']] as $suggestion): ?><div style="margin-top:10px;padding:10px;border-top:1px solid var(--line)"><span class="priority <?=e($suggestion['priority'])?>"><?=ucfirst(e($suggestion['priority']))?></span> <strong><?=e($suggestion['title'])?></strong><div class="muted"><?=e($suggestion['description'])?></div><?php if($suggestion['status']==='pending'&&is_manager()): ?><form method="post" action="audio_ai.php"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="audio_id" value="<?=$log['id']?>"><input type="hidden" name="suggestion_id" value="<?=$suggestion['id']?>"><input type="hidden" name="action" value="accept"><button class="button button-red">Accept as ticket</button></form><?php else: ?><span class="muted">Status: <?=e($suggestion['status'])?></span><?php endif; ?></div><?php endforeach; ?></div></div><?php endforeach; ?></div></section></div><script>
const btn=document.getElementById('recordButton'),hint=document.getElementById('recordHint'),timer=document.getElementById('timer'),file=document.getElementById('audioFile'),save=document.getElementById('saveButton'),duration=document.getElementById('duration');let rec,chunks=[],started,interval;btn.onclick=async()=>{if(rec?.state==='recording'){rec.stop();return}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});rec=new MediaRecorder(stream);chunks=[];rec.ondataavailable=e=>chunks.push(e.data);rec.onstop=()=>{stream.getTracks().forEach(t=>t.stop());const dt=new DataTransfer();dt.items.add(new File([new Blob(chunks,{type:'audio/webm'})],'recording.webm',{type:'audio/webm'}));file.files=dt.files;save.disabled=false;hint.textContent='Recording ready. Add context and save it.';document.getElementById('recorder').classList.remove('recording');clearInterval(interval)};rec.start();started=Date.now();document.getElementById('recorder').classList.add('recording');hint.textContent='Recording in progress — press the button to stop.';interval=setInterval(()=>{let s=Math.floor((Date.now()-started)/1000);duration.value=s;timer.textContent=String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')},1000)}catch(e){hint.textContent='Microphone unavailable. Choose an audio file instead.'}};file.onchange=()=>{if(file.files.length){save.disabled=false;hint.textContent=file.files[0].name+' ready to upload.'}};</script><?php require 'includes/footer.php';
